// GET /api/analytics/published-posts returns { posts: [...] } as ONE
// item -- split it into one n8n item per published post.
const posts = ($input.first().json && $input.first().json.posts) || [];
return posts.map((p) => ({ json: p }));

// publishedUrl looks like https://www.linkedin.com/feed/update/urn:li:share:12345
// -- pull the raw urn:li:... token back out, since LinkedIn's Social
// Actions API needs it (URL-encoded) as a path parameter, not the full URL.
return $input.all().map((item) => {
  const p = item.json;
  const match = (p.publishedUrl || "").match(/urn:li:[a-zA-Z]+:[a-zA-Z0-9]+/);
  const urn = match ? match[0] : null;
  return { json: { ...p, urn, encodedUrn: urn ? encodeURIComponent(urn) : null } };
});

// LinkedIn's socialActions endpoint gives likes + comments for content
// you own. It does NOT give impressions or share counts -- those require
// LinkedIn's Marketing API Partner Program (a separate, approval-gated
// partnership most developer apps don't have), so this workflow
// deliberately leaves "impressions"/"shares" out of the payload rather
// than fabricate numbers -- the app's schema already treats every metric
// field as optional for exactly this reason.
//
// Posts that failed the Social Actions call (continueOnFail on the
// previous node) are filtered out here rather than sent with fake zeros --
// no data this run is better than wrong data.
const originItems = $('Extract LinkedIn URN').all();

const results = $input.all()
  .filter((item) => !item.json.error && !item.json.errorMessage)
  .map((item) => {
    const originIdx = item.pairedItem ? item.pairedItem.item : undefined;
    const original = originIdx !== undefined ? originItems[originIdx].json : {};

    const likes = item.json.likesSummary ? item.json.likesSummary.totalLikes : null;
    const comments = item.json.commentsSummary
      ? (item.json.commentsSummary.aggregatedTotalComments ?? item.json.commentsSummary.totalFirstLevelComments ?? null)
      : null;

    return {
      scheduledPostId: original.scheduledPostId,
      capturedAt: new Date().toISOString(),
      likes,
      comments
    };
  })
  .filter((r) => Boolean(r.scheduledPostId));

return results.map((r) => ({ json: r }));
